class GenericRepository<T, ID> {
    EntityManager em; Class<T> type;
    void save(T t) { em.persist(t); }
    T findById(ID id) { return em.find(type, id); }
}
new GenericRepository<Employee, Long>(em, Employee.class);
new GenericRepository<Product, Long>(em, Product.class);

